style.css:
/* Estilo base para el html y el body para asegurar un fondo negro */
html, body {
    background-color: #000000 !important;
}

/* Estilo para contenedores principales y secciones */
div, article, section, main, aside, nav {
    background-color: #000000 !important;
    color: #00FF00 !important; /* Aseguramos que el texto siga siendo verde */
}

/* Estilo para otros elementos de bloque comunes */
p, ul, ol, li, blockquote, pre, hr, h1, h2, h3, h4, h5, h6, table, tr, td, th, tbody, thead, tfoot, form, fieldset, legend, textarea, select, input, button {
    background-color: #000000 !important;
    color: #00FF00 !important;
    border-color: #00FF00 !important; /* Si tienen bordes, también en verde */
}

/* Estilo para elementos en línea */
span, a, code, em, strong, abbr, acronym, cite, q, dfn, kbd, samp, var, sub, sup, label {
    color: #00FF00 !important;
}

/* Estilo específico para enlaces */
a {
    color: #00FF00 !important;
}

a:hover {
    color: #ADFF2F !important; /* Un verde más claro al pasar el ratón */
}

/* Para evitar fondos no deseados en elementos seleccionados */
::selection {
    background-color: #00FF00 !important;
    color: #000000 !important;
}

/* Para elementos con listas */
li {
    background-color: transparent !important; /* Aseguramos que el fondo del ítem de la lista sea transparente sobre el fondo negro del contenedor */
}

/* Para tablas, forzamos el color de fondo en celdas y filas */
table, tr, td, th {
    background-color: #000000 !important;
    border-color: #00FF00 !important;
}

/* Para formularios, aseguramos el color de fondo de los elementos */
input, textarea, select, button {
    background-color: #111111 !important; /* Un gris oscuro para los elementos de formulario */
    color: #00FF00 !important;
    border-color: #00FF00 !important;
}

/* Evitar fondos blancos en elementos con pseudo-clases */
::-webkit-input-placeholder { /* Chrome/Opera/Safari */
    color: #808080 !important; /* Un gris para el placeholder */
}

:-ms-input-placeholder { /* IE */
    color: #808080 !important;
}

::placeholder { /* Modern Browsers */
    color: #808080 !important;
}
